package io.invenlio.sales;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/v1/customers")@SecurityRequirement(name="bearerAuth")class CustomerController{private final CustomerService service;CustomerController(CustomerService s){service=s;}@Operation(summary="Create a draft customer")@PostMapping CustomerService.View create(@Valid@RequestBody Request r){return service.create(r.command());}@Operation(summary="List tenant customers",description="Filters by exact number, lifecycle status, or text; pages are bounded and sorting is allow-listed.")@GetMapping List<CustomerService.View>list(@RequestParam(required=false)String number,@RequestParam(required=false)String status,@RequestParam(required=false)String q,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(required=false)String sort){return service.list(number,status,q,page,size,sort);}@GetMapping("/{id}")CustomerService.View get(@PathVariable UUID id){return service.get(id);}@Operation(summary="Update customer master data")@PatchMapping("/{id}")CustomerService.View update(@PathVariable UUID id,@Valid@RequestBody Request r){return service.update(id,r.command(),r.version);}@PostMapping("/{id}/activate")CustomerService.View activate(@PathVariable UUID id,@RequestBody Version r){return service.lifecycle(id,"ACTIVE",r.version);}@PostMapping("/{id}/deactivate")CustomerService.View deactivate(@PathVariable UUID id,@RequestBody Version r){return service.lifecycle(id,"INACTIVE",r.version);}@PostMapping("/{id}/block")CustomerService.View block(@PathVariable UUID id,@RequestBody Version r){return service.lifecycle(id,"BLOCKED",r.version);}@PostMapping("/{id}/archive")CustomerService.View archive(@PathVariable UUID id,@RequestBody Version r){return service.lifecycle(id,"ARCHIVED",r.version);}
 record Request(@NotBlank@Size(max=200)String name,@Size(max=200)String legalName,@Email@Size(max=254)String email,@Size(max=40)String phone,@NotBlank String currency,@NotBlank@Size(max=1000)String shippingAddress,@Size(max=1000)String billingAddress,@PositiveOrZero long version){CustomerService.Command command(){return new CustomerService.Command(name,legalName,email,phone,currency,shippingAddress,billingAddress);}}record Version(@PositiveOrZero long version){}
}
